"""Freeze own East-to-North quarter with correct progressive front cargo occlusion."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[1];S=ROOT/'character/marsh-carry-turn-material-v1/sources'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
g=json.loads((S/'guide-provenance.json').read_text());pair='east-north'
prompt='''Create FOUR complete adult Marsh game sprites in one horizontal row with wide transparent gutters:THREE whole-body cargo turn poses from EAST screenRIGHT side toward NORTH back-facing away,then one NEUTRAL NORTH back standing ruler. ReferenceONE paired selected East/North idles is PRIMARY adult body/head/limb proportions,elevated camera and quiet warm matte pixel grade. LEFT board figure East faces RIGHT,RIGHT board figure North faces AWAY:keep these board positions. ReferenceTWO exact staged cargo endpoints gives rigid slate case,connected two-hand support and body/equipment identity. ReferenceTHREE original own EAST and referenceFOUR original own NORTH preserve swept blond hair,anatomicalRIGHT temple implant,backplate/harness/pouches/ankle buckles. No mirroring. No FRONT-facing turn poses:rotate toward BACK/away from camera.
Figure1 rotates22.5degrees from right side toward BACK:shallow REAR-RIGHT quarter,small part of backplate now visible,face still partly in RIGHT profile. Head/torso/pelvis/feet/case rotate together. Slate crate remains held IN FRONT OF HIS WAIST along heading,close to body,both bent arms supporting it. As back turns toward viewer,torso starts occluding the far portion of case. Small natural low supporting foot adjustment,short stride,no high knee/run/squat.
Figure2 rotates45degrees:clear REAR-RIGHT quarter,backplate and rear harness/pouches visible,only a small right-side face/ear glimpse. Same rigid supported waist case mostly occluded by torso,visible only around screenRIGHT side where projection allows. The case is always IN FRONT OF HIM,never strapped behind or carried on back. No box drawn across backplate. Hands wrap case ahead of torso,near bent elbow visible at side,far hand naturally hidden. Adult small head/body and equipment same size,quiet warm ivory/sage/slate/charcoal pixel material.
Figure3 rotates67.5degrees:nearly NORTH back-facing,slight REAR-RIGHT yaw. Mostly back of head,no frontal eyes/nose portrait,backplate near frontal to viewer. Case IN FRONT of wearer,now nearly completely hidden by torso,at most a narrow edge at screenRIGHT,never across lower back. Both arms bent gently forward away from viewer,supported case stays physically attached though occluded. Feet/support approach exact North endpoint in referenceTWO,short low pivot step,not both airborne. Authentic rear knee/ankle equipment and anatomicalRIGHT implant increasingly occluded near far/right rear edge;never swap sides.
Figure4 exact NEUTRAL NORTH back standing ruler from RIGHT figure of PRIMARY referenceONE,arms relaxed down,no crate,full unobstructed hair-to-sole adult body. One146 occupied neutral calibration,184canvas,p92/172,H148,no per-pose or cargo-width fitting. All four sprites complete separate figures,transparent empty gutters,no floor/background/shadow/glow/haze/text. Elevated station game camera and restrained small matte pixel clusters,not enlarged portrait. All three intermediate poses are REAR-RIGHT progressing from EAST side to NORTH BACK. The waist-held front case disappears behind the body as yaw approaches North;no backpack case.'''
p=S/'east-north-01.prompt.txt';assert not p.exists();p.write_text(prompt+'\n',encoding='utf-8')
refs=[S/f'{pair}-body-primary.png',S/f'{pair}-cargo-endpoints.png',ROOT/g['ownOriginalMasters']['east']['path'],ROOT/g['ownOriginalMasters']['north']['path']]
frames=[g[k][f] for k in ['primaryIdles','stagedEndpoints'] for f in ['east','north']]
(S/'east-north-01.request.json').write_text(json.dumps({'normalAdmission':False,'fullGoalComplete':False,'status':'frozen before generation; not started','promptSha256':sha(p),'orderedReferences':[{'path':q.relative_to(ROOT).as_posix(),'sha256':sha(q)} for q in refs],'sourceFrames':frames,'guideDependencies':[{'path':'tools/prepare_marsh_carry_turn_material_guides.py','sha256':sha(ROOT/'tools/prepare_marsh_carry_turn_material_guides.py')}],'sheetGrid':[4,1],'transparentBackground':True,'intermediateYawsFromEastDegrees':[22.5,45,67.5],'neutralOccupiedTargetHeight':146},indent=2)+'\n')
print('Frozen own East-North rear quarter,front-held crate progressively occluded;not generated.')
